+
+            @Override
+            public void afterBulk(long executionId, BulkRequest request, Exception failure) {
+                if (failure != null) {
+                    failureCount.incrementAndGet();
+                    exceptionRef.set(ExceptionsHelper.useOrSuppress(exceptionRef.get(), failure));
+
+                }
+            }
+        };
+    }
