+    }
+
+    @SuppressWarnings("unused")
+    private void runOtherAsyncAction(Object item, Releasable releasable) {
+        releasable.close();
+    }
+
+    private void runOneOffAsyncAction(Releasable releasable) {
+        releasable.close();
+    }
